/**
 * Version Refresh Service
 *
 * Detects when a new version is deployed and forces a hard refresh to prevent
 * users from loading stale JavaScript bundles that no longer exist on the server.
 *
 * Problem This Solves:
 * - User has old version cached in browser (e.g., 9.7.5 with old JS filenames)
 * - New version deploys (9.7.6) with new cache-busted JS filenames
 * - User requests old JS files that no longer exist
 * - Server returns index.html as 404 fallback
 * - Browser tries to execute HTML as JavaScript → SyntaxError: Unexpected token '<'
 *
 * Solution:
 * - On app startup, fetch /version.json from server
 * - Compare deployed version with current app version
 * - If different, force hard refresh with location.reload(true)
 * - Include retry logic and error handling
 *
 * Version Check Triggers:
 * - App initialization (main.ts)
 * - Every 5 minutes while user has app in focus
 * - When user returns from background (visibilitychange event)
 */

import { logger } from './logger';
import { getCacheRefreshProgressControls } from './cacheRefreshProgress';
import type { RefreshStep } from './cacheRefreshProgress';
import { CONSTANTS } from 'src/constants';

// HMR guard to prevent multiple initializations during hot reload
let isInitialized = false;

interface VersionInfo {
  version: string;
  timestamp?: string;
}

interface VersionCheckResult {
  currentVersion: string;
  deployedVersion: string | null;
  needsRefresh: boolean;
  error: string | null;
}

class VersionRefreshService {
  private currentVersion: string;
  private lastCheckedVersion: string | null = null;
  private checkInterval: NodeJS.Timeout | null = null;
  private visibilityHandler: (() => void) | null = null;
  private readonly CHECK_INTERVAL_MS = 300000; // Check every 5 minutes
  private readonly FETCH_TIMEOUT_MS = 5000;
  private readonly REFRESH_COOLDOWN_MS = 4 * 60 * 1000; // 4 minutes cooldown between auto-refreshes
  private readonly REFRESH_COOLDOWN_KEY = CONSTANTS.version_refresh_cooldown;

  // DOCB-14301 loop-breaker. Per-tab budget of automated recovery reloads.
  // Once exhausted we stop reloading and hand the user a manual-recovery
  // banner instead of an endless spinner.
  private readonly RELOAD_ATTEMPT_KEY = 'dbx_update_reload_attempts';
  private readonly MAX_RELOAD_ATTEMPTS = 2;
  // How long the app must run without any asset error before the loop guards
  // (`_refresh` URL marker, cooldown, attempt counter) are considered spent.
  private readonly HEALTHY_RUNTIME_MS = 60000;
  private healthyRuntimeTimer: ReturnType<typeof setTimeout> | null = null;
  private sawAssetErrorThisPage = false;

  constructor() {
    // Get current version from window.__APP_VERSION__ or package.json version
    this.currentVersion = this.getCurrentVersion();
  }

  /**
   * Initialize version check system
   * - Set up periodic checks
   * - Listen for visibility changes (user returns from background)
   * - Listen for asset preload errors (Vite/Chunk load failures)
   */
  initialize(): void {
    logger.debug('[VersionRefresh] Initializing version check service');
    logger.debug('[VersionRefresh] Current app version:', this.currentVersion);

    // Allow disabling version check via URL parameter or localStorage
    if (this.isVersionCheckDisabled()) {
      logger.warn('[VersionRefresh] Version check DISABLED (via URL param or localStorage)');
      return;
    }

    // Set up listeners for asset loading failures
    this.setupAssetErrorListeners();

    // Allow forcing overlay display for testing via URL parameter
    // Skip test mode if we already refreshed (prevents popup showing twice)
    if (typeof window !== 'undefined') {
      const urlParams = new URLSearchParams(window.location.search);
      if (urlParams.get('showVersionOverlay') === 'true' && !urlParams.has('_refresh')) {
        logger.warn('[VersionRefresh] TEST MODE - Forcing overlay via URL parameter');
        this.lastCheckedVersion = '9.32.10';
        this.performHardRefresh();
        return;
      }
    }

    // DOCB-14301: the `_refresh` marker and the cooldown are the ONLY things
    // standing between a recurring asset failure and an endless reload loop.
    // Stripping them at boot (as we used to) disarmed both guards on every
    // single page load — the loop then ran forever on sandbox. They are now
    // released only after the app has run HEALTHY_RUNTIME_MS without a single
    // asset error, which is the real signal that the previous refresh worked.
    this.scheduleHealthyRuntimeCleanup();

    // Check on startup
    this.checkVersion();

    // Set up periodic checks (every 5 minutes)
    if (typeof window !== 'undefined') {
      this.checkInterval = setInterval(() => {
        this.checkVersion();
      }, this.CHECK_INTERVAL_MS);

      // Also check when user returns from background
      // Store handler reference for cleanup
      this.visibilityHandler = () => {
        if (!document.hidden) {
          logger.debug('[VersionRefresh] User returned from background, checking version');
          this.checkVersion();
        }
      };
      document.addEventListener('visibilitychange', this.visibilityHandler);

      logger.debug('[VersionRefresh] Version check service initialized successfully');
    }
  }

  // Corroboration window: require 2+ asset errors within this window before reloading.
  // A single transient preload/stylesheet failure (flaky CDN, network blip) is NOT
  // a reason to reload — only a burst of them is.
  private readonly ASSET_ERROR_WINDOW_MS = 4000;
  private readonly ASSET_ERROR_THRESHOLD = 2;
  private assetErrorTimestamps: number[] = [];

  /**
   * Listen for asset loading failures (Vite preload errors, chunk load errors).
   *
   * IMPORTANT: Navigation-triggered chunk errors are already handled by
   * Router.onError (src/router/index.ts) and click-triggered async component
   * failures by the unhandledrejection handler in src/boot/main.js. This
   * listener ONLY handles the residual case: Vite preload/stylesheet failures
   * that neither of the other two catch.
   */
  private setupAssetErrorListeners(): void {
    if (typeof window === 'undefined') return;

    // Vite-specific dynamic import failure. Vite recommends preventing the
    // default throw and refreshing when a deployed app references old chunks.
    window.addEventListener('vite:preloadError', (event) => {
      event.preventDefault();
      this.refreshAfterConfirmedAssetError('Vite preload failure');
    });

    // Resource loading errors (modulepreload/preload/stylesheet <link> failures).
    // Deliberately narrower than before — does NOT catch generic script error
    // messages; those are handled by the unhandledrejection paths elsewhere.
    window.addEventListener('error', (event) => {
      const target = event.target as any;
      if (!target || target.tagName !== 'LINK') return;
      const rel = target.rel;
      if (rel === 'modulepreload' || rel === 'preload' || rel === 'stylesheet') {
        this.recordAssetError(`Resource failure: ${target.href}`);
      }
    }, true);
  }

  /**
   * Record an asset error and only trigger refresh when a burst of them
   * occurs within the corroboration window. This prevents single transient
   * failures (flaky CDN, one dropped packet) from nuking the user's session.
   */
  private recordAssetError(reason: string): void {
    // Offline? Not a version issue — user is just disconnected.
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
      logger.debug('[VersionRefresh] Asset error while offline, ignoring:', reason);
      return;
    }

    this.sawAssetErrorThisPage = true;

    // Already reloading or recently reloaded — don't pile on.
    if (this.isInCooldownPeriod()) {
      return;
    }

    if (this.isPostRefreshLoad()) {
      // We already tried a refresh — further errors mean the server really is
      // missing files, not a stale-cache issue. Don't loop; tell the user
      // instead of leaving them on a silently broken page (DOCB-14301).
      this.stopLoopAndRequireManualRecovery(reason);
      return;
    }

    const now = Date.now();
    this.assetErrorTimestamps = [
      ...this.assetErrorTimestamps.filter(t => now - t < this.ASSET_ERROR_WINDOW_MS),
      now,
    ];

    logger.warn(
      `[VersionRefresh] Asset error (${this.assetErrorTimestamps.length}/${this.ASSET_ERROR_THRESHOLD}):`,
      reason,
    );

    if (this.assetErrorTimestamps.length < this.ASSET_ERROR_THRESHOLD) {
      return;
    }

    logger.warn('[VersionRefresh] Asset error threshold reached, triggering refresh');
    this.assetErrorTimestamps = [];
    this.performDirectRefresh();
  }

  /**
   * A Vite preload error is stronger than a generic <link> failure: it means a
   * dynamic import required by the app could not be loaded. Waiting for a second
   * corroborating error can leave the user on a broken route, so refresh once.
   */
  private refreshAfterConfirmedAssetError(reason: string): void {
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
      logger.debug('[VersionRefresh] Confirmed asset error while offline, ignoring:', reason);
      return;
    }

    this.sawAssetErrorThisPage = true;

    if (this.isInCooldownPeriod()) {
      return;
    }

    if (this.isPostRefreshLoad()) {
      this.stopLoopAndRequireManualRecovery(reason);
      return;
    }

    logger.warn('[VersionRefresh] Confirmed asset error, triggering refresh:', reason);
    this.assetErrorTimestamps = [];
    void this.performDirectRefresh();
  }

  /**
   * Clean up periodic checks
   * Call this when app is unmounting or being destroyed
   */
  destroy(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = null;
    }
    if (this.visibilityHandler) {
      document.removeEventListener('visibilitychange', this.visibilityHandler);
      this.visibilityHandler = null;
    }
    if (this.healthyRuntimeTimer) {
      clearTimeout(this.healthyRuntimeTimer);
      this.healthyRuntimeTimer = null;
    }
    logger.debug('[VersionRefresh] Version check service destroyed');
  }

  /**
   * Check if version check should be disabled
   * Supports URL parameter (?disableVersionCheck=true) or localStorage flag
   */
  private isVersionCheckDisabled(): boolean {
    if (typeof window === 'undefined') {
      return false;
    }

    // Vite dev server (`quasar dev`): the served bundle's package.json
    // version NEVER matches the deployed vdeployment version, so the
    // watchdog would reload the app in an endless ?_refresh loop — this
    // killed Playwright CI specs and local dev sessions mid-interaction
    // (DRFS-664 CI stabilization). The check only makes sense for real
    // builds; `process.env.DEV` is statically true only under `quasar dev`.
    if (process.env.DEV) {
      return true;
    }

    // Check URL parameter
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('disableVersionCheck') === 'true') {
      return true;
    }

    // Check localStorage flag
    try {
      return localStorage.getItem('disableVersionCheck') === 'true';
    } catch {
      return false;
    }
  }

  /**
   * Check if we're in cooldown period after user clicked "Refresh Now"
   * Prevents annoying popup reappearing during page reload
   */
  private isInCooldownPeriod(): boolean {
    if (typeof window === 'undefined') {
      return false;
    }

    try {
      const cooldownUntil = localStorage.getItem(this.REFRESH_COOLDOWN_KEY);
      if (!cooldownUntil) return false;
      const isInCooldown = Date.now() < parseInt(cooldownUntil, 10);
      if (isInCooldown) {
        logger.debug('[VersionRefresh] In cooldown period, skipping notification');
      }
      return isInCooldown;
    } catch {
      return false;
    }
  }

  /**
   * Set cooldown period to prevent popup from showing during refresh
   */
  private setCooldown(): void {
    try {
      const cooldownUntil = Date.now() + this.REFRESH_COOLDOWN_MS;
      localStorage.setItem(this.REFRESH_COOLDOWN_KEY, String(cooldownUntil));
      logger.debug('[VersionRefresh] Set cooldown until:', new Date(cooldownUntil).toISOString());
    } catch {
      // localStorage might not be available
    }
  }

  /**
   * Clear cooldown period (called when versions match)
   */
  private clearCooldown(): void {
    try {
      localStorage.removeItem(this.REFRESH_COOLDOWN_KEY);
    } catch {
      // localStorage might not be available
    }
  }

  /**
   * Is this page load itself the result of an automated refresh?
   * (`_refresh` marker survives until the healthy-runtime cleanup runs.)
   */
  private isPostRefreshLoad(): boolean {
    if (typeof window === 'undefined') return false;
    try {
      return new URLSearchParams(window.location.search).has('_refresh');
    } catch {
      return false;
    }
  }

  /**
   * Read the per-tab automated-reload budget.
   *
   * Scoped to the running build: a genuinely new deployment gets a fresh
   * budget instead of inheriting the previous build's exhausted one.
   */
  private readReloadAttempts(): number {
    if (typeof window === 'undefined') return 0;
    try {
      const raw = sessionStorage.getItem(this.RELOAD_ATTEMPT_KEY);
      if (!raw) return 0;
      const parsed = JSON.parse(raw) as { count?: unknown; version?: unknown };
      if (parsed?.version !== this.currentVersion) return 0;
      const count = Number(parsed?.count);
      return Number.isFinite(count) && count > 0 ? count : 0;
    } catch {
      return 0;
    }
  }

  /**
   * Record one automated reload attempt.
   *
   * Returns the new attempt number, or -1 when sessionStorage is unavailable
   * or the write does not read back. -1 means the counter has no memory across
   * reloads; the caller then leans on the `_refresh` URL marker, which travels
   * with the navigation and bounds the loop on its own.
   */
  private recordReloadAttempt(): number {
    if (typeof window === 'undefined') return -1;
    const next = this.readReloadAttempts() + 1;
    try {
      sessionStorage.setItem(
        this.RELOAD_ATTEMPT_KEY,
        JSON.stringify({ count: next, version: this.currentVersion, ts: Date.now() }),
      );
      // Read back: private-mode / extension-blocked storage accepts the write
      // and silently drops it, which would make every reload look like the first.
      return this.readReloadAttempts() === next ? next : -1;
    } catch {
      return -1;
    }
  }

  private clearReloadAttempts(): void {
    try {
      sessionStorage.removeItem(this.RELOAD_ATTEMPT_KEY);
    } catch {
      // sessionStorage might not be available
    }
  }

  /**
   * Stop the automated reload loop and surface the manual-recovery banner.
   *
   * This is the terminal state of the loop-breaker: no more reloads, no
   * spinner — an actionable, dismissible message instead (DOCB-14301).
   */
  private stopLoopAndRequireManualRecovery(reason: string): void {
    logger.error(
      '[VersionRefresh] Automated recovery exhausted — stopping the reload loop.',
      `Reason: ${reason}. Version: ${this.currentVersion}.`,
      'The user must hard-reload (Ctrl+Shift+R) or clear site data.',
    );
    try {
      getCacheRefreshProgressControls().requireManualRecovery(this.currentVersion);
    } catch (err) {
      logger.warn('[VersionRefresh] Could not show manual recovery banner:', err);
    }
  }

  /**
   * Release the loop guards only after the app has proven healthy.
   *
   * "Healthy" = HEALTHY_RUNTIME_MS of runtime with zero asset errors. Doing
   * this at boot instead (the old behaviour) disarmed every guard on the very
   * page load that was about to fail again — that is what turned a single
   * asset failure into an endless reload loop on sandbox (DOCB-14301).
   */
  private scheduleHealthyRuntimeCleanup(): void {
    if (typeof window === 'undefined') return;

    this.healthyRuntimeTimer = setTimeout(() => {
      this.healthyRuntimeTimer = null;

      if (this.sawAssetErrorThisPage) {
        logger.warn(
          '[VersionRefresh] Asset errors seen on this page — keeping loop guards armed',
        );
        return;
      }

      logger.debug('[VersionRefresh] Healthy runtime reached, releasing loop guards');
      this.clearReloadAttempts();
      this.cleanupRefreshParam();
      this.clearCooldown();
    }, this.HEALTHY_RUNTIME_MS);
  }

  /**
   * Remove _refresh query parameter from URL after successful page load.
   * Without this, the param persists and blocks all future refresh overlays.
   */
  private cleanupRefreshParam(): void {
    if (typeof window === 'undefined') return;
    try {
      const url = new URL(window.location.href);
      if (url.searchParams.has('_refresh')) {
        url.searchParams.delete('_refresh');
        window.history.replaceState({}, '', url.toString());
        logger.debug('[VersionRefresh] Cleaned up _refresh param from URL');
      }
    } catch {
      // URL parsing or history API might fail in some environments
    }
  }

  /**
   * Get current app version
   * Try multiple sources for robustness
   */
  private getCurrentVersion(): string {
    // Try reading from CI/CD environment variable (set during deployment) - PRIMARY
    if (process.env.APP_VUE_CURRENT_VERSION) {
      return process.env.APP_VUE_CURRENT_VERSION.toString();
    }

    // Try window global (legacy fallback)
    if (typeof window !== 'undefined' && (window as any).__APP_VERSION__) {
      return (window as any).__APP_VERSION__;
    }

    // Try APP_VERSION from quasar.config.cjs (read from version.txt at build time)
    // This is available in local dev when CI/CD vars are not set
    if (process.env.APP_VERSION) {
      return process.env.APP_VERSION.toString();
    }

    // Final fallback - development version
    return '0.1.2';
  }

  /**
   * Check if deployed version differs from current version
   */
  private async checkVersion(): Promise<VersionCheckResult> {
    try {
      const deployed = await this.fetchDeployedVersion();

      const result: VersionCheckResult = {
        currentVersion: this.currentVersion,
        deployedVersion: deployed,
        needsRefresh: deployed !== null && deployed !== this.currentVersion,
        error: null,
      };

      if (result.needsRefresh) {
        logger.warn(
          '[VersionRefresh] Version mismatch detected!',
          `Current: ${result.currentVersion}, Deployed: ${result.deployedVersion}`
        );
        // Store deployed version so overlay can display it
        this.lastCheckedVersion = deployed;
        this.performHardRefresh();
      } else if (deployed && deployed === this.currentVersion) {
        // Versions match, no refresh needed
        if (this.lastCheckedVersion !== deployed) {
          logger.debug('[VersionRefresh] Versions match, app is up to date');
          this.lastCheckedVersion = deployed;
        }
        // Clear any stale cooldown since we're on the latest version.
        //
        // DOCB-14301: NOT while this page load is itself the product of a
        // refresh, and not while the reload budget is partly spent. "Versions
        // match" is exactly the state the loop lives in — the asset-error path
        // does not compare versions, so clearing the cooldown here re-armed
        // the loop on every boot. The healthy-runtime timer clears it instead.
        if (!this.isPostRefreshLoad() && this.readReloadAttempts() === 0) {
          this.clearCooldown();
        }
      }

      return result;
    } catch (err) {
      logger.error('[VersionRefresh] Error checking version:', err);
      return {
        currentVersion: this.currentVersion,
        deployedVersion: null,
        needsRefresh: false,
        error: String(err),
      };
    }
  }

  /**
   * Fetch version.json from server
   * This file is generated during deployment with current app version
   */
  private async fetchDeployedVersion(): Promise<string | null> {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), this.FETCH_TIMEOUT_MS);

      // Base-path aware so the frozen bundle reads its own /vesta/version.json
      // instead of the root (latest) file. Cache-bust query param defeats
      // edge/CDN caches that ignore the `cache: 'no-cache'` request hint.
      const base = import.meta.env.BASE_URL || '/';
      const response = await fetch(`${base}version.json?t=${Date.now()}`, {
        signal: controller.signal,
        cache: 'no-cache',
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        logger.warn('[VersionRefresh] Failed to fetch version.json:', response.status);
        return null;
      }

      const versionInfo: VersionInfo = await response.json();
      return versionInfo.version || null;
    } catch (err) {
      // Network errors, timeouts, etc. are expected during development
      // Don't spam logs with these - just return null
      if (err instanceof TypeError && err.message.includes('Failed to fetch')) {
        logger.debug('[VersionRefresh] Network error fetching version.json (expected in offline)');
      } else {
        logger.debug('[VersionRefresh] Error fetching deployed version:', err);
      }
      return null;
    }
  }

  /**
   * Auto-refresh to the newly deployed version.
   *
   * No popup, no "Refresh Now" prompt — when a new version is live the app
   * reloads straight onto it (a brief progress overlay still shows so the user
   * understands the reload). The cooldown guard prevents a tight reload loop if
   * a CDN edge is still serving the old bundle: we retry at most once per
   * cooldown window rather than hammering reloads.
   */
  private performHardRefresh(): void {
    if (typeof window === 'undefined') {
      return; // Don't auto-refresh in SSR
    }

    // Recently auto-refreshed already — don't loop while the new bundle
    // propagates through caches/CDN.
    if (this.isInCooldownPeriod()) {
      logger.debug('[VersionRefresh] In cooldown, skipping auto-refresh');
      return;
    }

    logger.warn(
      '[VersionRefresh] New version detected — auto-refreshing to load it',
      `New version ${this.lastCheckedVersion} is available`,
    );

    void this.performDirectRefresh();
  }

  /**
   * Clear service worker caches
   * This ensures the browser loads fresh assets after version update
   */
  private async clearCaches(): Promise<boolean> {
    let fallbackId1: ReturnType<typeof setTimeout>;
    let fallbackId2: ReturnType<typeof setTimeout>;
    let timedOut = false;
    try {
      if ('caches' in window) {
        const cacheNames = await Promise.race([
          caches.keys(),
          new Promise<string[]>(resolve => { fallbackId1 = setTimeout(() => { timedOut = true; resolve([]); }, 3000); }),
        ]);
        await Promise.race([
          Promise.all(cacheNames.map(name => caches.delete(name))),
          new Promise<void>(resolve => { fallbackId2 = setTimeout(() => { timedOut = true; resolve(); }, 3000); }),
        ]);
        logger.info(`[VersionRefresh] Cleared ${cacheNames.length} cache(s)`);
        return !timedOut;
      }
      return true; // no caches API → nothing stale to clear
    } catch (err) {
      logger.warn('[VersionRefresh] Error clearing caches:', err);
      return false;
    } finally {
      clearTimeout(fallbackId1!);
      clearTimeout(fallbackId2!);
    }
  }

  /**
   * Unregister all service workers
   */
  private async unregisterServiceWorkers(): Promise<boolean> {
    let timeoutId: ReturnType<typeof setTimeout>;
    let fallbackId: ReturnType<typeof setTimeout>;
    let timedOut = false;
    const timeout = new Promise<never>((_, reject) => {
      timeoutId = setTimeout(() => reject(new Error('timeout')), 4000);
    });
    try {
      if ('serviceWorker' in navigator) {
        const registrations = await Promise.race([
          navigator.serviceWorker.getRegistrations(),
          timeout,
        ]);
        await Promise.race([
          Promise.all(registrations.map(reg => reg.unregister())),
          new Promise<void>(resolve => { fallbackId = setTimeout(() => { timedOut = true; resolve(); }, 3000); }),
        ]);
        logger.info(`[VersionRefresh] Unregistered ${registrations.length} service worker(s)`);
        return !timedOut;
      }
      return true; // no SW API → nothing to unregister
    } catch (err) {
      logger.warn('[VersionRefresh] Error/timeout unregistering service workers — continuing anyway:', err);
      return false;
    } finally {
      clearTimeout(timeoutId!);
      clearTimeout(fallbackId!);
    }
  }

  /**
   * Clear localStorage items that may cause version conflicts
   * Preserves auth tokens and user preferences
   */
  private clearLegacyVersionStorage(): void {
    try {
      // Dead legacy keys — safe to drop unconditionally. The real baseline
      // (CONSTANTS.app_version) is handled separately, only after cleanup
      // succeeds, so a failed clear leaves pwaCache's retry signal intact.
      const keysToRemove = ['appVersion', 'lastKnownVersion', 'cacheVersion'];
      keysToRemove.forEach(key => localStorage.removeItem(key));
      logger.info('[VersionRefresh] Cleared legacy version-related localStorage items');
    } catch (err) {
      logger.warn('[VersionRefresh] Error clearing legacy localStorage:', err);
    }
  }

  private clearStoredVersionBaseline(): void {
    try {
      // CONSTANTS.app_version ('APP_VERSION') is the real baseline pwaCache reads.
      localStorage.removeItem(CONSTANTS.app_version);
      logger.info('[VersionRefresh] Cleared stored app-version baseline');
    } catch (err) {
      logger.warn('[VersionRefresh] Error clearing app-version baseline:', err);
    }
  }

  /**
   * Small delay for visual feedback during progress
   */
  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Perform the actual hard refresh with progress tracking.
   * Adds timestamp to URL to bypass cache. Includes loop prevention
   * to avoid infinite refresh cycles for *automated* triggers
   * (e.g. vite preloadError fallback). Pass `userInitiated: true`
   * to bypass that guard — an explicit "Refresh Now" click is intent
   * and must always show the overlay + clear caches, even if the URL
   * still carries `_refresh` from a prior cycle.
   */
  private async performDirectRefresh(
    options: { userInitiated?: boolean } = {},
  ): Promise<void> {
    if (typeof window === 'undefined') {
      return;
    }

    const refreshUrl = new URL(window.location.href);

    // LOOP PREVENTION: skip ONLY for automated refreshes. A user-clicked
    // "Refresh Now" is explicit intent — they expect the overlay and a
    // clean cache wipe even if the URL already carries `_refresh` from
    // a previous reload cycle.
    if (!options.userInitiated && this.isPostRefreshLoad()) {
      // DOCB-14301: this used to return silently, leaving the user on a broken
      // page (or, worse, under a spinner). Reloading again cannot help — the
      // last reload already failed to fix it. Tell them what to do instead.
      this.stopLoopAndRequireManualRecovery('already refreshed once for this issue');
      return;
    }

    // DOCB-14301 loop-breaker: spend one unit of the per-tab reload budget.
    // An exhausted budget means stop, don't loop.
    if (!options.userInitiated) {
      const attempt = this.recordReloadAttempt();
      if (attempt < 0) {
        // Storage is blocked (private mode, extensions) so the counter cannot
        // survive the reload. Do NOT refuse the refresh — a legitimate update
        // must still land. The `_refresh` URL marker travels with the
        // navigation and bounds this to a single automated reload on its own.
        logger.warn(
          '[VersionRefresh] Session storage unavailable — falling back to the _refresh URL marker to bound the loop',
        );
      } else if (attempt > this.MAX_RELOAD_ATTEMPTS) {
        this.stopLoopAndRequireManualRecovery(
          `reload budget exhausted (${attempt}/${this.MAX_RELOAD_ATTEMPTS})`,
        );
        return;
      }
      logger.warn(
        `[VersionRefresh] Automated refresh attempt ${attempt}/${this.MAX_RELOAD_ATTEMPTS}`,
      );
    }

    // Set cooldown before refresh to prevent popup from reappearing during reload
    this.setCooldown();

    // Get progress controls
    const progressControls = getCacheRefreshProgressControls();
    const { STEPS } = progressControls;

    // DOCB-14301: only announce an UPDATE when there genuinely is one. The
    // asset-error recovery path does not compare versions at all, and
    // `lastCheckedVersion` holds the *matching* deployed version once a
    // version check has succeeded — which rendered "v10.59.3.1 → v10.59.3.1"
    // over an endless "Reloading application..." spinner on sandbox.
    const targetVersion = this.lastCheckedVersion;
    const isVersionUpdate = !!targetVersion && targetVersion !== this.currentVersion;

    // Step 1: Start overlay.
    // Shown for a real version update, and for an explicit user-initiated
    // refresh (they clicked; they deserve feedback). Suppressed for silent
    // same-version recovery reloads — the caption is dropped too, so the
    // overlay can never claim "vX → vX".
    const overlayShown =
      isVersionUpdate || options.userInitiated
        ? progressControls.start(
            this.currentVersion,
            isVersionUpdate ? (targetVersion as string) : '',
          )
        : false;

    if (!overlayShown) {
      logger.warn(
        '[VersionRefresh] Recovery reload without a version change — update overlay suppressed',
        `current=${this.currentVersion} target=${targetVersion ?? 'none'}`,
      );
    }

    const step = (s: RefreshStep) => {
      if (overlayShown) progressControls.updateProgress(s);
    };
    const pause = (ms: number) => (overlayShown ? this.delay(ms) : Promise.resolve());

    await pause(300);

    // Step 2: Clear legacy localStorage (real baseline dropped after cleanup)
    step(STEPS.CLEAR_LOCALSTORAGE);
    this.clearLegacyVersionStorage();
    await pause(400);

    // Step 3: Clear caches
    step(STEPS.CLEAR_CACHES);
    const cachesCleared = await this.clearCaches();
    await pause(400);

    // Step 4: Unregister service workers
    step(STEPS.UNREGISTER_SW);
    const swUnregistered = await this.unregisterServiceWorkers();
    await pause(400);

    // Drop the version baseline ONLY once cleanup is confirmed complete.
    // Keeping it on failure preserves pwaCache's boot-time retry signal so the
    // next load re-attempts the clear instead of trusting a stale cache.
    if (cachesCleared && swUnregistered) {
      this.clearStoredVersionBaseline();
    } else {
      logger.warn('[VersionRefresh] Cleanup incomplete — keeping APP_VERSION so the next boot retries the cache clear');
    }

    // Step 5: Prepare reload
    step(STEPS.PREPARE);
    await pause(500);

    // Step 6: Reload - show 100% briefly before reloading
    if (overlayShown) {
      progressControls.complete();
      await pause(600);
    }

    // Cache-busting reload. The `_refresh` marker is not decoration:
    //  - it makes the navigation URL unique, so neither the browser cache nor
    //    the Workbox precache (which matches the bare `index.html` entry) can
    //    hand back the stale document we are trying to escape;
    //  - it survives into the next page load as the loop guard, and is only
    //    dropped once the app has run healthily (scheduleHealthyRuntimeCleanup).
    // `replace` rather than `href` so a recovery cycle does not stack history
    // entries the user has to back-button through.
    refreshUrl.searchParams.set('_refresh', String(Date.now()));
    this.navigateTo(refreshUrl.toString());
  }

  /**
   * Navigate to `url`, preferring replace() so a recovery cycle does not stack
   * history entries. Falls back to an href assignment where replace() is not
   * callable (test environments, embedded webviews) — the navigation matters
   * more than the history semantics.
   */
  private navigateTo(url: string): void {
    try {
      window.location.replace(url);
    } catch (err) {
      logger.warn('[VersionRefresh] location.replace unavailable, falling back to href:', err);
      window.location.href = url;
    }
  }

  /**
   * Public method to manually trigger version check
   */
  async manualCheck(): Promise<VersionCheckResult> {
    logger.debug('[VersionRefresh] Manual version check requested');
    return this.checkVersion();
  }

  /**
   * Get current check status
   */
  getStatus() {
    return {
      currentVersion: this.currentVersion,
      lastCheckedVersion: this.lastCheckedVersion,
      isMonitoring: this.checkInterval !== null,
    };
  }
}

// Create singleton instance
let versionRefreshService: VersionRefreshService | null = null;

/**
 * Get or create version refresh service instance
 */
export function getVersionRefreshService(): VersionRefreshService {
  if (!versionRefreshService) {
    versionRefreshService = new VersionRefreshService();
  }
  return versionRefreshService;
}

/**
 * Initialize version refresh on app startup
 * Call this in main.ts before app is mounted
 */
export function initializeVersionRefresh(): void {
  // Prevent re-initialization during HMR
  if (isInitialized && import.meta.hot) {
    logger.debug('[VersionRefresh] Skipping re-initialization (HMR)');
    return;
  }

  const service = getVersionRefreshService();
  service.initialize();

  isInitialized = true;
  logger.info('[VersionRefresh] Version refresh service initialized');
}

/**
 * Clean up version refresh service
 * Call this when app is unmounting
 */
export function destroyVersionRefresh(): void {
  if (versionRefreshService) {
    versionRefreshService.destroy();
    versionRefreshService = null;
  }
}

export { VersionRefreshService, VersionCheckResult, VersionInfo };

// HMR cleanup - reset state when module is replaced
if (import.meta.hot) {
  import.meta.hot.dispose(() => {
    logger.debug('[VersionRefresh] HMR dispose - cleaning up');
    destroyVersionRefresh();
    isInitialized = false;
  });
}
